import { isObject } from "@eoussama/core";
import * as z from "zod/mini";



/*
 * The one definition of a link: the TypeScript types, the check of links.json and the
 * editor schema (links.schema.json, generated by `pnpm schema`) all come from here.
 */

/** A slug as it may appear in `links.json`: lowercase letters, digits and dashes. */
export const SLUG_PATTERN = /^[a-z0-9][a-z0-9-]*$/;

const email = z.email({ error: "Must be an email address." });

// Text with a lone surrogate is valid JSON but can't be percent-encoded: it would crash every click.
const text = z.string().check(z.refine(value => value.isWellFormed(), { error: "Must not contain broken Unicode characters." }));
const addresses = z.union([email, z.array(email).check(z.minLength(1, { error: "Must list at least one address." }))]);

/** A link to a web page. */
export const urlLinkSchema = z.strictObject({
  url: z.httpUrl({ error: "Must be an absolute http or https URL." })
    .check(z.regex(/^https?:\/\//i))
    .register(z.globalRegistry, { description: "The target, an absolute http or https URL." }),
  permanent: z.optional(z.boolean().register(z.globalRegistry, { description: "Answer with 301 (cached by browsers) instead of 302." })),
});

/** A link that opens a prefilled email. */
export const mailtoLinkSchema = z.strictObject({
  mailto: z.email({ error: "Must be an email address." }).register(z.globalRegistry, { description: "The recipient's address." }),
  subject: z.optional(text),
  body: z.optional(text),
  cc: z.optional(addresses),
  bcc: z.optional(addresses),
});

export const linkSchema = z.union([urlLinkSchema, mailtoLinkSchema]);

/** The links, keyed by slug. */
export const linksSchema = z.record(z.string().check(z.regex(SLUG_PATTERN)), linkSchema, {
  error: issue => issue.code === "invalid_key" ? "Slugs must be lowercase letters, digits and dashes." : undefined,
});

/**
 * The link map from `links.json`, checked. It runs in `pnpm validate`, so a broken entry
 * fails `pnpm check` (and the deploy) instead of a visitor's click, and again when the
 * Worker starts. The editor's `$schema` key is skipped.
 *
 * @param input - The parsed JSON
 * @returns The links, by slug
 */
export function validateLinks(input: unknown): Readonly<z.infer<typeof linksSchema>> {
  const entries = isObject(input) ? Object.fromEntries(Object.entries(input).filter(([key]) => key !== "$schema")) : input;

  // Zod skips a `__proto__` key without checking it, so slugs are checked here as well.
  const badSlug = isObject(entries) ? Object.keys(entries).find(slug => !SLUG_PATTERN.test(slug)) : undefined;

  if (badSlug !== undefined) {
    throw new Error(`links.json is invalid:\n✖ Slugs must be lowercase letters, digits and dashes.\n  → at ${badSlug}`);
  }

  const result = linksSchema.safeParse(entries);

  if (!result.success) {
    throw new Error(`links.json is invalid:\n${z.prettifyError(result.error)}`);
  }

  return Object.freeze(result.data);
}

/**
 * The JSON Schema editors use to check and autocomplete `links.json`.
 *
 * @returns The schema
 */
export function linksJsonSchema(): Record<string, unknown> {
  const schema = z.toJSONSchema(linksSchema) as Record<string, unknown>;

  return {
    $schema: schema.$schema,
    title: "Redirector links",
    description: "The links served at to.ouss.es, keyed by slug.",
    ...schema,
    // The `$schema` key that points editors here is allowed next to the slugs.
    properties: { $schema: { type: "string" } },
    propertyNames: { anyOf: [{ const: "$schema" }, schema.propertyNames] },
  };
}
